/**
 * Contracts shared INSIDE the Electron UI app (main ⇄ preload ⇄ renderer):
 * the IPC surface, persisted settings, CLI detection and the daemon connection
 * handle. Nothing here describes the daemon's HTTP API, and there are no secret
 * identifiers — the app stores no credentials (see the Secrets section below).
 *
 * The daemon's wire shapes are NOT mirrored here. They are generated from its
 * own OpenAPI document into `apps/ui/src/renderer/autogenerated` by
 * `pnpm generate:api`, and the renderer imports them from there — so a route or
 * schema change on the daemon surfaces as a type error after regeneration
 * instead of silently drifting from a hand-written copy.
 */

import type { RemoteAccessState } from './remote';
import { DEFAULT_THEME_PREFERENCE, type ThemePreference } from './themes';

// ─────────────────────────────────────────────────────────────────────────────
// Daemon connection (read from the pidfile by main, passed to the renderer)
// ─────────────────────────────────────────────────────────────────────────────

/** Connection coordinates the renderer needs to open an authed WS/HTTP call. */
export interface DaemonHandle {
  /** Loopback host the daemon reported binding to (from the pidfile). */
  host: string;
  /** Loopback port the daemon reported binding to. */
  port: number;
  /** Per-launch bearer token; required on every daemon request. */
  token: string;
  /**
   * Reach the daemon over https/wss rather than http/ws.
   *
   * Absent on every handle main reads from the pidfile — the daemon itself
   * only ever speaks plain http on loopback. Set by the remote bridge alone,
   * when the page was served over a TLS origin (a tunnel's public address):
   * a browser refuses an http request from an https page as mixed content,
   * so the scheme has to follow the page's.
   */
  secure?: boolean;
  /** Daemon version (semver). */
  version: string;
  /**
   * When THIS daemon launch began (ISO-8601, from the pidfile).
   *
   * Carried for one reason, and it is a liveness one rather than a display one:
   * an agent's CLI process cannot outlive the daemon that spawned it, so
   * anything a transcript shows as still running whose row predates this
   * stamp is definitionally over — see `Chats.tsx`'s `shellsByAgent`, where a
   * detached command is otherwise listed on the strength of a settle row the
   * dead daemon never got to write.
   */
  startedAt: string;
}

/** One step of the data migration a starting daemon runs before it serves. */
export interface DaemonMigration {
  id: string;
  /** 1-based, among this start's pending migrations. */
  step: number;
  of: number;
}

/** Live status the renderer polls/subscribes to for the connection banner. */
export interface DaemonStatus {
  connected: boolean;
  handle: DaemonHandle | null;
  /** The step a starting daemon is migrating the user's data through; null otherwise. */
  migrating: DaemonMigration | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Settings (non-secret app config — persisted as JSON in userData)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Bounds on the saved run configurations. Here rather than beside the IPC
 * schema because three places must agree and only two are in main: that schema,
 * the settings READ path (which salvages entry-by-entry and so never evaluates
 * the array bound), and the renderer's editors, which refuse a save before the
 * IPC throws and discards the whole patch.
 */
export const MAX_RUN_CONFIGS = 50;
export const MAX_RUN_CONFIG_NAME = 80;

/**
 * A saved new-chat setup the user named — a bundle of COMPOSER state and
 * nothing more. Choosing one seeds the normal new-chat screen; it creates no
 * run and reaches the daemon only later, through the ordinary create call.
 *
 * The daemon-vocabulary fields (`target`, `model`, `effort`, `approval`) are
 * OPAQUE strings, as the single-value settings beside them are: this file holds
 * no daemon shapes, and the renderer checks each against the generated enum
 * before it reaches a run. `null` means "the CLI's own default" everywhere.
 *
 * NOT a {@link FastAction}, and the two must never be folded together again.
 * A configuration answers "where and with what does this chat run"; an action
 * answers "what do I say". Collapsing them made an action usable in exactly one
 * setup and gave the run's configuration a second, invisible source — so they
 * are two lists, two editors, and two keys in settings.json.
 */
export interface RunConfig {
  id: string;
  name: string;
  /** Absolute working directory the chat starts in. */
  cwd: string;
  /**
   * Branch the folder should be on, or null to take whatever is checked out.
   *
   * NOT a chat field — no branch reaches the daemon. Applying one is a guarded
   * `git switch` on `cwd` before the chat is created, which refuses over a dirty
   * tree; that refusal is surfaced and the rest of the configuration still
   * applies.
   */
  branch: string | null;
  /** The composer target — a CLI kind or `team:<slug>`, exactly as `lastChatTarget`. */
  target: string;
  model: string | null;
  effort: string | null;
  /** Which of the model's context-window sizes; null = the model's own. */
  contextWindow: string | null;
  /**
   * The OTHER model settings, keyed by the CLI's own parameter id; `{}` = the
   * model's own defaults. Opaque here for the reason every CLI vocabulary is.
   */
  modelParameters: Record<string, string>;
  /** The daemon's `ChatApprovalMode`. */
  approval: string | null;
  /** Plugin/profile directory, or null for the CLI's own account. */
  configDir: string | null;
  /**
   * The project a run started from this configuration belongs to, whatever
   * folder it runs in: its instructions reach every agent of the run. Absent or
   * null leaves it to the folder; an id naming a deleted project reads as null.
   */
  projectId?: string | null;
}

/**
 * Bounds on the fast actions. Here rather than beside the IPC schema because
 * three places must agree and only two are in main: that schema, the settings
 * READ path (which salvages entry-by-entry and so never evaluates the array
 * bound), and the renderer's editor, which refuses a save before the IPC throws
 * and discards the whole patch.
 */
export const MAX_FAST_ACTIONS = 50;
export const MAX_FAST_ACTION_NAME = 80;
/**
 * How long a fast action's description may be.
 *
 * Generous rather than tight: this is a whole brief the user writes once and
 * fires many times — "review the diff on this branch against our conventions
 * and report findings" is the short end of it. The cap is a guard against a
 * renderer bug growing settings.json without limit, not an editorial opinion.
 */
export const MAX_FAST_ACTION_TEXT = 4000;

/**
 * A named piece of text the user drops into the composer with one press.
 *
 * A NAME and a DESCRIPTION, and deliberately nothing else. It carries no
 * folder, no agent, no model and no approval mode, so it is usable under
 * whatever the composer is already set to — which is the whole of what makes it
 * fast. An action that also chose the setup would be a second, invisible place
 * the run's configuration came from, and pressing one would silently move the
 * chips the user had just set.
 */
export interface FastAction {
  id: string;
  name: string;
  /** The instruction a press writes into the message box. Never sent by itself. */
  description: string;
}

/**
 * How many named configurations a user may keep, and how long a name may be.
 *
 * Hand-managed like the fast actions and the run configurations beside them, so
 * the cap is a guard against a renderer bug growing settings.json without
 * limit rather than an editorial opinion — nobody keeps twenty accounts.
 */
export const MAX_CONFIG_PROFILES = 20;
export const MAX_CONFIG_PROFILE_NAME = 40;

/**
 * The app's ONE colour palette, as token NAMES.
 *
 * The same eight the chat sidebar's groups already use, over the same
 * `--color-group-*` tokens — one palette in the app, so a blue profile and a
 * blue group are the same blue. It is spelled here rather than derived from the
 * daemon's `RunGroupColor`, and that is forced rather than chosen: this file is
 * ELECTRON-internal and holds no daemon shapes (see the renderer rules), while
 * a profile's colour lives in settings.json and never reaches the daemon at
 * all. The renderer is where the two meet, and it maps both through one lookup
 * (`components/ui/palette.ts`) so the classes cannot drift even though the unions
 * must stay separate.
 */
export const PROFILE_COLORS = [
  'blue',
  'purple',
  'green',
  'orange',
  'pink',
  'indigo',
  'teal',
  'red',
] as const;
export type ProfileColor = (typeof PROFILE_COLORS)[number];

/** The longest name a browser tab may carry. TWIN: `BROWSER_TAB_NAME_MAX` in `apps/daemon/src/v1/browser/browser.types.ts`. */
export const BROWSER_TAB_NAME_MAX = 60;

/** A tab name holds no control or format character, so it stays one plain line wherever it is shown or listed. */
export const BROWSER_TAB_NAME_PATTERN = /^[^\p{Cc}\p{Cf}]*$/u;

/**
 * One of the user's named agent configurations — a config directory with a name
 * and a colour on it.
 *
 * A config directory is the profile a CLI runs as: its credentials, its
 * plugins, its history. The app has always been able to point a run at one, but
 * only ever by PATH — so a user with three accounts picked between
 * `/Users/x/.claude-work`, `/Users/x/.claude-personal` and
 * `/Users/x/.claude-lab` by reading their tails. A name says which account it
 * is in the user's own words, and a colour is what makes it recognisable
 * without reading at all.
 *
 * The DIRECTORY is the identity and the only field a run consumes; the name and
 * colour are labelling over it. So two entries may not name the same directory
 * — that would be two names for one account, and nothing could say which of
 * them a run was using.
 */
export interface ConfigProfile {
  id: string;
  name: string;
  /**
   * The CLI whose config directory this is. A profile is offered to that CLI
   * alone: each CLI keeps a different layout in its directory, so another
   * CLI pointed at it signs in as nobody and writes its own files there.
   */
  agent: CliKind;
  /** Absolute path to the agent config directory this profile stands for. */
  dir: string;
  color: ProfileColor;
}

/**
 * The transcript page sizes a user can pick. A short list rather than a number
 * field: each is a size somebody chose, and the daemon refuses a page over
 * 5,000 rows.
 */
export const HISTORY_PAGE_SIZES = [250, 500, 1000, 2000] as const;
export type HistoryPageSize = (typeof HISTORY_PAGE_SIZES)[number];
export const DEFAULT_HISTORY_PAGE_SIZE: HistoryPageSize = 1000;

/**
 * How long, in minutes, a run's CLI process (and every MCP server it started)
 * is kept after its last turn — `Settings.keptSessionIdleMinutes`.
 *
 * TWIN: `DEFAULT_KEPT_SESSION_IDLE_MINUTES`, `MIN_KEPT_SESSION_IDLE_MINUTES`
 * and `MAX_KEPT_SESSION_IDLE_MINUTES` in `apps/daemon/src/v1/agents/chat.types.ts`,
 * whose route refuses a value outside these bounds.
 */
export const DEFAULT_KEPT_SESSION_IDLE_MINUTES = 60;
export const MIN_KEPT_SESSION_IDLE_MINUTES = 5;
export const MAX_KEPT_SESSION_IDLE_MINUTES = 180;

/**
 * How many run CLI processes may be kept at once — `Settings.keptSessionLimit`.
 *
 * TWIN: `MIN_KEPT_SESSION_LIMIT` and `MAX_KEPT_SESSION_LIMIT` in
 * `apps/daemon/src/v1/agents/chat.types.ts`, whose route refuses a value
 * outside these bounds.
 */
export const MIN_KEPT_SESSION_LIMIT = 2;
export const MAX_KEPT_SESSION_LIMIT = 64;

/** Persisted, non-secret application settings. Secrets never live here. */
export interface OnboardingProgress {
  step: 0 | 1 | 2 | 3;
  agent: CliKind | null;
  route: 'chat' | 'team' | 'explore';
  teamMethod: 'ai' | 'example' | 'graph' | 'import';
  brief: string;
}

/** Who runs an analysis or a change chat — see `Settings.lastAnalysisConfig`. */
export interface AnalysisConfig {
  agent: CliKind;
  /** The profile (config directory), or null for the CLI's own. */
  configDir: string | null;
  model: string | null;
  effort: string | null;
  contextWindow: string | null;
  /** The auto-compact threshold, or null for never. */
  autoCompactPercent: number | null;
  modelParameters: Record<string, string>;
  /**
   * The tool-approval mode, opaque for `lastApprovalMode`'s reason; null =
   * auto-approve, the analysis default (it works unwatched in its popup).
   */
  approval: string | null;
}

/**
 * Who sorts a memory import with AI, and everything it runs with — a chat's
 * model settings; see `Settings.lastMemoryTriage`.
 */
export interface MemoryTriageConfig {
  agent: CliKind;
  /** The profile (config directory), or null for the CLI's own. */
  configDir: string | null;
  model: string | null;
  effort: string | null;
  contextWindow: string | null;
  modelParameters: Record<string, string>;
}

/**
 * One place encrypted share links are uploaded to, reached through the user's
 * own CLI and login (`gcloud`, `aws`, or a program of their own as argv).
 *
 * TWIN PARSER: `ShareDestinationSchema` in
 * `apps/daemon/src/v1/shares/shares.types.ts`, which receives these values
 * (`PUT /v1/shares/config`); the shape and its limits are restated in
 * `main/ipc-schemas.ts`. A field added here goes in both.
 */
export type ShareDestination =
  | {
      kind: 'gcs';
      id: string;
      name: string;
      /** https origin the objects are served from; the link is `<linkBase>/<path>#k=<key>`. */
      linkBase: string;
      bucket: string;
      prefix?: string;
    }
  | {
      kind: 's3';
      id: string;
      name: string;
      linkBase: string;
      bucket: string;
      prefix?: string;
      profile?: string;
      region?: string;
    }
  | {
      kind: 'command';
      id: string;
      name: string;
      linkBase: string;
      /** argv tokens; `{file}` and `{object}` are substituted, nothing runs through a shell. */
      upload: string[];
      remove: string[];
      /**
       * How to sign the CLI in again (argv) and which output means it is
       * signed out (case-insensitive substrings). Without it a program named
       * `gcloud` or `aws` borrows that CLI's own sign-in.
       */
      signIn?: { login?: string[]; patterns?: string[] };
    };

export interface SharingSettings {
  destinations: ShareDestination[];
  /** Where a press (and an agent) shares to; null shares nowhere. */
  defaultDestinationId: string | null;
  /** Whether an agent's `show_artifact(share: true)` may upload. Off unless turned on. */
  agentsMayShare: boolean;
  /** Revoke a page this many days after it was first shared; null never does. */
  autoRevokeAfterDays: number | null;
}

export const DEFAULT_SHARING: SharingSettings = {
  destinations: [],
  defaultDestinationId: null,
  agentsMayShare: false,
  autoRevokeAfterDays: null,
};

/** Whether an agent's memory write is saved at once or waits for the user's review. */
export type MemoryAgentWrites = 'active' | 'pending';

export interface MemorySettings {
  /** Off gives agents no memory tools. */
  enabled: boolean;
  agentWrites: MemoryAgentWrites;
  /**
   * Each CLI's own memory off in new runs while the shared memory is on. Off
   * by default, so the CLIs' notes are never hidden before the user imports
   * them; a successful import turns it on.
   */
  nativeMemoryOff: boolean;
}

export const DEFAULT_MEMORY: MemorySettings = {
  enabled: true,
  agentWrites: 'active',
  nativeMemoryOff: false,
};

/** Whether a thread is reflected on when it is archived: never, or automatically. */
export type LessonsMode = 'off' | 'auto';

/**
 * What a lessons reflection and its optional check run as. A null `reflector`
 * reflects as the thread did — its CLI and profile — on that CLI's light model;
 * a null `checker` runs no check.
 *
 * TWIN PARSER: `LessonsConfigSchema` in `apps/daemon/src/v1/lessons/lessons.types.ts`,
 * which `main/lessons-config-push.ts` pushes this to.
 */
export interface LessonsSettings {
  mode: LessonsMode;
  reflector: MemoryTriageConfig | null;
  checker: MemoryTriageConfig | null;
}

export const DEFAULT_LESSONS: LessonsSettings = {
  mode: 'auto',
  reflector: null,
  checker: null,
};

/** What an agent's document save does: used at once, held for the user's review, or refused. */
export type KnowledgeAgentWrites = 'review' | 'direct' | 'off';

export interface KnowledgeSettings {
  /** Off gives agents no knowledge tools and no index. */
  enabled: boolean;
  agentWrites: KnowledgeAgentWrites;
}

export const DEFAULT_KNOWLEDGE: KnowledgeSettings = {
  enabled: true,
  agentWrites: 'direct',
};

export interface ResourceAlertSettings {
  /** Off stops the daemon reading process, memory and disk figures at all. */
  enabled: boolean;
  threadMemoryBytes: number;
  growthBytesPerMinute: number;
  minFreeDiskBytes: number;
}

export const DEFAULT_RESOURCE_ALERTS: ResourceAlertSettings = {
  enabled: true,
  threadMemoryBytes: 8 * 1024 ** 3,
  growthBytesPerMinute: 1024 ** 3,
  minFreeDiskBytes: 10 * 1024 ** 3,
};

export interface Settings {
  /**
   * The settings migration this file was last brought up to
   * (`main/settings-migrations.ts`); 0 for a file that predates versioning.
   * Main's alone: the renderer's patch schema refuses it.
   */
  settingsVersion: number;
  /** First-run onboarding finished (gates the renderer's initial route). */
  onboardingComplete: boolean;
  /** Resumable setup choices; contains no credentials. */
  onboardingProgress: OnboardingProgress | null;
  /** Absolute path to the user's working project folder (agent cwd). */
  projectFolder: string | null;
  /** Recently used project folders, most recent first (composer suggestions). */
  recentFolders: string[];
  /**
   * The config directory the next new chat loads, per CLI — absent for a CLI
   * on its own default profile. The composer's optional companion to
   * `projectFolder`, so a user who works under one profile (a different
   * subscription, a different toolbelt) does not re-pick it per chat. Each
   * chat records its OWN, so this is only the picker's default.
   *
   * Keyed per CLI like `lastModels`, because the directories are not
   * interchangeable: a claude profile handed to codex as `CODEX_HOME` is a
   * signed-out codex writing its files into the claude profile.
   */
  configDirs: Partial<Record<CliKind, string>>;
  /** Recently used config directories per CLI, most recent first. */
  recentConfigDirs: Partial<Record<CliKind, string[]>>;
  /**
   * The user's saved new-chat setups (see {@link RunConfig}). A managed LIST,
   * unlike `recentFolders`/`recentConfigDirs` beside it: nothing adds or evicts
   * an entry, and the order is the user's, so it is never re-sorted on read.
   */
  runConfigs: RunConfig[];
  /**
   * The user's fast actions (see {@link FastAction}). A managed LIST, unlike
   * `recentFolders`/`recentConfigDirs` beside it: nothing adds or evicts an
   * entry, and the order is the user's, so it is never re-sorted on read.
   */
  fastActions: FastAction[];
  /**
   * The user's named agent configurations (see {@link ConfigProfile}) — a
   * managed LIST on exactly the terms of the two above: nothing adds or evicts
   * an entry, and the order is the user's, so it is never re-sorted on read.
   *
   * Distinct from `recentConfigDirs`, which is an MRU of raw paths this file
   * DOES re-sort. The two answer different questions — "where have I pointed a
   * chat lately" against "which accounts do I have" — and folding them would
   * mean a name and a colour the app was free to evict.
   */
  configProfiles: ConfigProfile[];
  /** The chat composer's last target — a CLI kind or `team:<slug>`. */
  lastChatTarget: string | null;
  /**
   * The new-run composer's last approval mode, so it opens on the choice the
   * user actually works in rather than resetting to `ask` every time. An
   * opaque string here on purpose: the mode vocabulary is the DAEMON's (its
   * `ChatApprovalMode`), and this file holds no daemon shapes — the renderer
   * validates the stored value against the generated enum before applying it.
   */
  lastApprovalMode: string | null;
  /**
   * The new-run composer's last model per CLI. Keyed by CLI because the two
   * have disjoint model vocabularies — one shared slot would hand cursor a
   * claude alias the moment the user switched agents. A missing entry means
   * that CLI's own default (no `--model` flag).
   */
  lastModels: Partial<Record<CliKind, string>>;
  /**
   * The new-run composer's last reasoning-effort level per CLI. Keyed per CLI
   * for the same reason as `lastModels`, and opaque here for the same reason
   * as `lastApprovalMode`: the vocabulary belongs to the CLI (the daemon asks
   * its adapter), so this file cannot name the levels. A missing entry means
   * that CLI's own default — which is also every CLI that has no such control.
   */
  lastEfforts: Partial<Record<CliKind, string>>;
  /**
   * The new-run composer's last context-window size per CLI, on exactly the
   * terms `lastEfforts` is remembered — keyed per CLI, opaque here, and a
   * missing entry meaning the model's own default.
   *
   * Remembered even though the sizes belong to the MODEL rather than the CLI:
   * a user who works at `1m` wants `1m` on the next chat too, and a size the
   * next model does not offer costs nothing — the chip re-fetches that model's
   * own list and draws the stored value as unavailable rather than sending it.
   */
  lastContextWindows: Partial<Record<CliKind, string>>;
  /**
   * The new-run composer's last auto-compact threshold (a percentage of the
   * context window), or null for never. ONE value rather than one per CLI: a
   * share of the window means the same thing to every agent.
   */
  lastAutoCompactPercent: number | null;
  /**
   * The setup last used in a chat that improves something: a thread's or a
   * team's analysis, a team's or a project's chat. Written when one starts from
   * the analysis dialog and when its settings are changed in the chat; the next
   * of any of them opens on it. Null until then (the dialog starts from the
   * composer's setup, a change chat from the CLI's defaults).
   */
  lastAnalysisConfig: AnalysisConfig | null;
  /**
   * The approval mode last chosen in a team's or a project's chat, opaque for
   * `lastApprovalMode`'s reason. Apart from `lastAnalysisConfig.approval`, whose
   * auto-approve must not reach a chat whose changes wait on the user's press.
   */
  lastChangeChatApproval: string | null;
  /**
   * The memory import's "Sort with AI" last choice, so the next sort opens on
   * it; null until one has been made.
   */
  lastMemoryTriage: MemoryTriageConfig | null;
  /**
   * The OTHER model settings for the next chat on each CLI, as
   * `{parameterId: value}` — `{optimize_for: 'balanced'}`.
   *
   * Remembered per CLI on the same terms as the window above, and opaque on
   * this side for the reason every daemon vocabulary is: the ids and the values
   * belong to the CLI (`shared/contracts.ts` holds no daemon shapes), so this
   * process stores strings and the renderer checks them against the model's own
   * listing before they reach a run.
   */
  lastModelParameters: Partial<Record<CliKind, Record<string, string>>>;
  /** Explicit overrides for CLI binary locations (else resolved on PATH). */
  cliPaths: Partial<Record<CliKind, string>>;
  /** Whether to check for app updates on launch (wired in M4). */
  checkForUpdates: boolean;
  /**
   * Whether the left nav rail is collapsed to its icon-only width.
   *
   * Persisted rather than session state because the rail is the one piece of
   * chrome a user sets ONCE to suit how they work — a wide window with the
   * labels on, a narrow one without — and re-collapsing it on every launch
   * made the choice look like it had not been taken.
   */
  sidebarCollapsed: boolean;
  /**
   * Post system notifications — a banner outside the app when an agent stops to
   * ask something, and when a thread's turn ends.
   *
   * ONE switch for both, not one per kind: they are the same interruption seen
   * from two sides of the same turn, and a user who does not want the app
   * talking to them outside its window does not want half of it. Defaults ON —
   * a thread parked on a question nobody sees is the failure this exists to
   * fix, so the useful state is the default and the switch is there to quiet
   * it.
   */
  notificationsEnabled: boolean;
  /**
   * Whether this machine serves the app's own interface to the local network,
   * so a phone on the same Wi-Fi can open the same live sessions.
   *
   * Defaults ON, which is only defensible because of what stands behind it: a
   * device's first visit has to type a six-digit code shown on this screen,
   * the listener refuses a Host header it does not recognise, and the daemon's
   * own token never leaves this machine. Off, the port is never opened at all.
   *
   * It governs the GATEWAY (`main/remote/`) and not the daemon, which goes on
   * binding loopback only whatever this says.
   */
  remoteAccessEnabled: boolean;
  /**
   * Where artifacts are shared to as encrypted links, and whether agents may
   * share. Owned here (settings.json) and pushed to every daemon this app
   * starts; the daemon keeps it in memory only. Desktop only: a paired device
   * may not write it.
   */
  sharing: SharingSettings;
  /**
   * Whether agents get memory tools, and whether their writes wait for the
   * user's review. Owned here (settings.json) and pushed to every daemon this
   * app starts; the daemon keeps it in memory only.
   */
  memory: MemorySettings;
  /**
   * Whether a thread is offered a lessons reflection, and the agent, model and
   * effort one runs as. Owned here and pushed to every daemon this app starts.
   */
  lessons: LessonsSettings;
  /**
   * Whether agents get knowledge tools and an index, and what happens to a
   * document an agent saves. Owned here (settings.json) and pushed to every
   * daemon this app starts; the daemon keeps it in memory only.
   */
  knowledge: KnowledgeSettings;
  /**
   * When the daemon warns about a thread's processes eating memory, the system
   * running short of memory, or the Data volume running short of space. Owned
   * here (settings.json) and pushed to every daemon this app starts; the
   * daemon keeps it in memory only.
   */
  resourceAlerts: ResourceAlertSettings;
  /**
   * Delete a chat this many days after it was ARCHIVED, or `null` to keep the
   * archive for ever.
   *
   * The archive is where a thread goes to stop cluttering the desk, and until
   * this existed nothing ever took anything out again — so it grew for the life
   * of the install and the only way back was the one-way delete, per row.
   *
   * **`null` is the default, and it is the only defensible one.** What this
   * switches on is the SAME irreversible delete the archive's own button
   * performs — rows, attachments, call tokens and all, with no trash and none
   * planned — so shipping it on would destroy conversations on the next launch
   * for every user who had never been asked, including threads archived months
   * ago that they may well still want. The window a user picks is theirs; the
   * silence is ours.
   *
   * A NUMBER of days rather than a boolean beside a constant, because the two
   * facts are one: "sweep the archive" and "how long is long enough" have no
   * separate answers, and a boolean pointing at a fixed 30 could not express
   * the ninety somebody else wants.
   */
  archiveRetentionDays: number | null;
  /**
   * Forget a memory entry that has gone cold for this many days, or `null` to
   * never forget on its own. Pushed to the daemon beside `memory` (as
   * `autoForgetAfterDays`), which runs the sweep daily; the sweep only forgets
   * and never purges.
   *
   * `null` is the default: forgetting what agents remember is the user's call.
   */
  memoryAutoForgetAfterDays: number | null;
  /**
   * Forget an entry that more threads marked not useful than helped, so no
   * agent sees it until the user restores it from Forgotten; its batch is
   * deleted for good 30 days later. Pushed to the daemon beside `memory` (as
   * `removeNotUseful`), which applies it on every mark and in its daily sweep.
   *
   * On by default: an entry that three more threads found unhelpful than helped
   * is the case the user would want removed, and Undo stays for 30 days.
   */
  memoryRemoveNotUseful: boolean;
  /**
   * How many transcript items one fetch of a chat brings back — the WINDOW a
   * thread opens on and pages through. Only the transcript's own rows depend on
   * it: every readout beside them is read from the daemon over the whole run.
   */
  historyPageSize: HistoryPageSize;
  /**
   * How long a run's CLI process is kept after its last turn, in minutes,
   * the same for a chat and a card's run. Main pushes it to every daemon
   * (`kept-session-config-push.ts`); the daemon holds it in memory only.
   *
   * An hour by default: claude keeps a subscription's prompt cache for an
   * hour, and a fresh `--resume` misses it once `git status` has changed, so a
   * shorter window pays a cache rewrite and a cold MCP start on the next turn.
   */
  keptSessionIdleMinutes: number;
  /**
   * How many run CLI processes the daemon keeps at once, or null for the
   * number it picks from this Mac's memory. Pushed with the idle window.
   */
  keptSessionLimit: number | null;
  /**
   * Keep the Mac from idle sleep while any agent works, and only then
   * (`main/keep-awake.ts`). The display still sleeps, and so does a closed lid.
   */
  preventSleepWhileWorking: boolean;
  /**
   * Each CLI's own switches — cursor's Max Mode, claude's browser tools, and
   * whatever a CLI declares next — as `{agentKind: {optionId: on}}`. The
   * daemon publishes every CLI's options (label, description, default) on
   * `GET /v1/capabilities`, so this side holds the user's CHOICES and nothing
   * else: an option absent here reads as that option's own default.
   *
   * SNAPSHOTTED per run — sent on chat create, team start and task run —
   * so flipping one changes the next run rather than one already open.
   */
  agentOptions: Partial<Record<CliKind, Record<string, boolean>>>;
  /**
   * Keep the transcript's intermediate steps FOLDED — a turn's tool calls stay
   * closed however interesting the app judges them.
   *
   * The default is off, which is the behaviour that was itself asked for: an
   * edit opens on its diff, because "I wanna see all file edits, so it should
   * be automatically open, like claude cli". This is the other reading of the
   * same transcript, reported by the same user against a turn that edited a
   * dozen files — "хочу настройку, чтобы автоматически коллапсить все
   * промежуточные шаги… при которой группа остается закрытой по дефолту" — so
   * it is a preference rather than a correction, and it is stated as one.
   *
   * It decides only what is OPEN when a row first appears. Every row is still
   * drawn, still counted in its group's header, and still one press away.
   */
  collapseToolSteps: boolean;
  /**
   * Spawn the daemon with a Node inspector on loopback, so real Chrome
   * DevTools can attach to it from `chrome://inspect`.
   *
   * The daemon is a separate Node process, so the renderer's DevTools can see
   * nothing of it. This is what closes that gap, and it is the genuine article
   * rather than a reimplementation: Sources with breakpoints over the daemon's
   * own TypeScript, the CPU profiler, heap snapshots.
   *
   * **Three states, not two.** `null` is "not chosen", which resolves per
   * build — on in dev, off when packaged (`resolveDaemonInspect`) — and an
   * explicit boolean overrides that either way.
   *
   * A plain boolean could not express this, because dev and the packaged app
   * share ONE userData dir (`app.setName('Geniro')` decides it, and both
   * builds set the same name). Whatever a dev launch resolved would be
   * written to the same settings.json a shipped launch then reads, so a
   * boolean default would leak the dev answer into the packaged build — the
   * exact case the split exists to prevent.
   */
  daemonInspect: boolean | null;
  /**
   * Standing instructions handed to EVERY agent, on every provider.
   *
   * Free prose, the user's own words. It reaches a CLI through the daemon's
   * one composition seam (`AgentAdapter.composeSystemPrompt`), so it needs no
   * per-CLI spelling here — which is also why there is one box rather than one
   * per agent.
   *
   * geniro's OWN preamble is NOT stored here. That text is a daemon constant
   * prepended ahead of this one and served back for display over
   * `GET /v1/capabilities`; keeping it out of settings.json is what stops a
   * user's edit silently deleting the app's correction to the CLI's "you are
   * writing to a terminal" system prompt.
   *
   * SNAPSHOTTED per run at creation, like `configDir` beside it: a run keeps
   * the text it started with, so editing this changes the next chat rather
   * than respawning the CLI process of one already open.
   */
  customInstructions: string;
  /**
   * The language every agent is told to reply in ("Russian"); `''` when the
   * user has set none, which leaves the choice to the model.
   *
   * A name, not prose: the daemon writes it into one sentence of its own and
   * into claude's `--settings`, and refuses one past
   * {@link REPLY_LANGUAGE_MAX_LENGTH}. Snapshotted per run like
   * `customInstructions`.
   */
  replyLanguage: string;
  /**
   * Which theme the app paints, or `'system'` to follow the OS.
   *
   * The names and their values live in `shared/themes.ts` and
   * `renderer/styles/themes/`; this holds only the choice. It is applied by
   * MAIN rather than by the renderer — `nativeTheme.themeSource` drives both
   * the OS chrome this app does not paint (the traffic lights, context menus,
   * system dialogs) and the renderer's own `prefers-color-scheme`, so one
   * write covers every surface and the two can never disagree.
   */
  theme: ThemePreference;
}

/**
 * Bounds of `Settings.lastAutoCompactPercent`.
 *
 * TWIN PARSER: `MIN_AUTO_COMPACT_PERCENT` / `MAX_AUTO_COMPACT_PERCENT` in the
 * daemon's `apps/daemon/src/v1/agents/chat.types.ts`, which `AutoCompactPercentSchema`
 * is built from. The generated client carries no bounds, so this copy exists to
 * stop a remembered threshold being one the next chat create refuses — change
 * one, change the other.
 */
export const MIN_AUTO_COMPACT_PERCENT = 10;
export const MAX_AUTO_COMPACT_PERCENT = 95;

/**
 * Whether a custom-instructions value carries a control character.
 *
 * TWIN PARSER: `hasControlCharacters` in
 * `apps/daemon/src/v1/agents/chat.types.ts`, which is the ENFORCING side (the
 * value reaches a child's argv there, where node rejects a NUL synchronously).
 * This copy exists because STORING a value the daemon will refuse turns one
 * invisible pasted character into a 400 on every new chat and team run,
 * surfacing in the composer with nothing pointing back at the settings box
 * holding it. Refusing where the text is typed is what keeps the two honest.
 * Change one, change the other.
 *
 * A code-point scan rather than a regex, for the same two reasons the twin
 * gives: raw bytes in the source make git treat the file as binary (the
 * `pre-commit` hook refuses it), and escapes trip eslint's `no-control-regex`.
 */
export function hasControlCharacters(value: string): boolean {
  for (let i = 0; i < value.length; i += 1) {
    const code = value.charCodeAt(i);
    if (code < 0x20 && code !== 0x09 && code !== 0x0a && code !== 0x0d) {
      return true;
    }
  }
  return false;
}

/**
 * The longest reply-language name `Settings.replyLanguage` holds. TWIN of the
 * daemon's `REPLY_LANGUAGE_MAX_LENGTH` (`v1/agents/chat.types.ts`), for
 * {@link hasControlCharacters}' reason: a value stored here and refused there
 * fails every new run.
 */
export const REPLY_LANGUAGE_MAX_LENGTH = 64;

/**
 * Whether `value` can be stored as `Settings.replyLanguage`: within the bound
 * and one line, with no control, invisible or bidirectional character. TWIN of
 * the daemon's `ReplyLanguageSchema` (over `utils/hidden-text.ts`), stricter
 * only on emoji sequences, which a language's name never needs.
 */
export function isReplyLanguage(value: string): boolean {
  return (
    value.trim().length <= REPLY_LANGUAGE_MAX_LENGTH &&
    !/[\p{Cc}\p{Cf}\p{Default_Ignorable_Code_Point}\u2028\u2029]/u.test(value)
  );
}

/** The settings every run snapshots at creation, as a create-payload fragment. */
export interface RunSettings {
  customInstructions?: string;
  replyLanguage?: string;
  agentOptions?: Partial<Record<CliKind, Record<string, boolean>>>;
}

/**
 * The run-start fragment for these settings — the one normalisation every run
 * start uses (the renderer's `currentRunSettings`, main's autopilot). Each key
 * is present only when set: blank collapses to absent so an untouched box and
 * a cleared one reach the daemon identically. `agentOptions` is sent whenever
 * the map exists, even all `false` — the daemon reads an absent id as that
 * option's default, so a declined switch must not look untouched.
 */
export function runSettingsOf(
  settings: Partial<
    Pick<Settings, 'customInstructions' | 'replyLanguage' | 'agentOptions'>
  >,
): RunSettings {
  const {
    customInstructions = '',
    replyLanguage = '',
    agentOptions,
  } = settings;
  const language = replyLanguage.trim();
  return {
    ...(customInstructions.trim() ? { customInstructions } : {}),
    ...(language === '' ? {} : { replyLanguage: language }),
    ...(agentOptions === undefined ? {} : { agentOptions }),
  };
}

/** Default settings written on first launch when no settings file exists. */
export const DEFAULT_SETTINGS: Settings = {
  settingsVersion: 0,
  onboardingComplete: false,
  onboardingProgress: null,
  projectFolder: null,
  recentFolders: [],
  configDirs: {},
  recentConfigDirs: {},
  runConfigs: [],
  fastActions: [],
  configProfiles: [],
  lastChatTarget: null,
  lastApprovalMode: null,
  lastModels: {},
  lastEfforts: {},
  lastContextWindows: {},
  lastAutoCompactPercent: null,
  lastAnalysisConfig: null,
  lastChangeChatApproval: null,
  lastMemoryTriage: null,
  lastModelParameters: {},
  cliPaths: {},
  checkForUpdates: true,
  sidebarCollapsed: false,
  notificationsEnabled: true,
  remoteAccessEnabled: true,
  sharing: DEFAULT_SHARING,
  memory: DEFAULT_MEMORY,
  lessons: DEFAULT_LESSONS,
  knowledge: DEFAULT_KNOWLEDGE,
  resourceAlerts: DEFAULT_RESOURCE_ALERTS,
  archiveRetentionDays: null,
  memoryAutoForgetAfterDays: null,
  memoryRemoveNotUseful: true,
  historyPageSize: DEFAULT_HISTORY_PAGE_SIZE,
  keptSessionIdleMinutes: DEFAULT_KEPT_SESSION_IDLE_MINUTES,
  keptSessionLimit: null,
  preventSleepWhileWorking: true,
  agentOptions: {},
  collapseToolSteps: false,
  daemonInspect: null,
  customInstructions: '',
  replyLanguage: '',
  theme: DEFAULT_THEME_PREFERENCE,
};

/**
 * Whether this launch spawns the daemon with an inspector.
 *
 * Unchosen means ON in dev and OFF when packaged, which is the honest default
 * on both sides rather than one compromise for both. Developing the app is
 * debugging it — there is no argument for making that a click — while a
 * shipped install has a user who will never attach a debugger and gains
 * nothing from the port, so the only thing an always-on default would add
 * there is arbitrary code execution inside the daemon for anything that
 * reaches loopback. That daemon spawns CLIs with the user's own permissions
 * over their source tree, and its env can still carry a credential the user
 * exported themselves — geniro no longer puts one there, which lowers the
 * stakes without removing them.
 *
 * (Node's inspector does validate the `Host` header, so a random web page
 * cannot attach — the exposure is to local processes, not to the network.
 * That is a real limit on the risk, and still not zero.)
 *
 * An explicit choice always wins, in both directions: a developer who
 * switched it off keeps it off, and a user who switched it on in a packaged
 * build keeps it on.
 */
export function resolveDaemonInspect(
  setting: boolean | null,
  isPackaged: boolean,
): boolean {
  return setting ?? !isPackaged;
}

/**
 * Loopback port the daemon's inspector listens on when `daemonInspect` is on.
 *
 * 9229 deliberately — it is node's own default, and the one address
 * `chrome://inspect` discovers with no configuration. A tidier private port
 * would mean every user's first step is "add 127.0.0.1:<x> under Configure",
 * which is the step people give up at.
 *
 * The Electron MAIN process is never launched with `--inspect` here, so
 * nothing else in this app claims it. If something outside does, node reports
 * the address as in use and the daemon still starts — the inspector is the
 * only thing lost.
 */
export const DAEMON_INSPECT_PORT = 9229;

// ─────────────────────────────────────────────────────────────────────────────
// App updates (GitHub Releases → download → checksum → swap the bundle in
// place; see main/update-service.ts and main/update-installer.ts)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Where the app is in noticing, fetching and applying an update.
 *
 * One phase list for both surfaces that show it — the banner over the views and
 * the Settings section — because they are two views of one process and a second
 * vocabulary is where the two would start disagreeing about what is happening.
 *
 * `ready` is the brief window between a swapped bundle and the relaunch: the
 * update is already ON DISK there, so a failure after it is not a failed update.
 */
export type UpdatePhase =
  | 'idle'
  | 'checking'
  | 'up-to-date'
  | 'available'
  | 'downloading'
  | 'installing'
  | 'ready'
  | 'error';

/** The whole of what main knows about updating, pushed on every change. */
export interface UpdateState {
  phase: UpdatePhase;
  /** The version being offered/fetched/installed; null when there is none. */
  version: string | null;
  /** 0–1 while `downloading`, null in every other phase. */
  progress: number | null;
  /** One line for the user: the failure, or what is happening right now. */
  message: string | null;
  /**
   * Which phase was in flight when {@link phase} became `error`; null whenever
   * it is not.
   *
   * `error` is an ending and so erases what failed, which left every failure
   * described as "The update could not be installed." — REPORTED against a
   * DOWNLOAD that never moved a byte, on an app that had installed nothing.
   * The distinction is the actionable half: a failed check is a network
   * problem, a stalled download is a bigger one, and a failed install is the
   * only one of the three that has touched the bundle.
   */
  failedPhase: UpdatePhase | null;
  /** The running app's version, so a screen can state it without a second call. */
  currentVersion: string;
  /**
   * Whether THIS install can replace itself.
   *
   * False for an unpackaged launch and for a bundle the user cannot write (a
   * copy owned by another account, a read-only mount, a translocated quarantine
   * copy). The surfaces read it to decide between an "Update now" button and
   * naming {@link UPDATE_COMMAND} — an update button that cannot work is worse
   * than a sentence saying which command does.
   */
  canInstall: boolean;
}

/** The one command that updates an install this app cannot replace itself. */
export const UPDATE_COMMAND = 'brew upgrade --cask geniro';

// ─────────────────────────────────────────────────────────────────────────────
// The window's own title bar (the OS draws none — see main/index.ts and
// components/nav-rail.tsx)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Where macOS puts the window buttons — `trafficLightPosition`.
 *
 * `y` is not a free choice: the buttons are 13.5px tall and every top row in
 * the shell is `h-11`, so (44 - 13.5) / 2 ≈ 15 is what centres them on that
 * row. Moving one without the other puts the system's buttons off the baseline
 * the whole strip is aligned to.
 */
export const TRAFFIC_LIGHT_INSET = { x: 10, y: 16 } as const;

/**
 * How wide the three-button group actually is.
 *
 * MEASURED, not assumed — assuming is precisely what broke it. This was taken
 * as 52px, which is what macOS drew for years (12px buttons, 20px apart). On
 * macOS 26 they are 13.5px and 23px apart, a **59.5px** group, so every
 * reservation derived from the old figure came up ~8px short and the green
 * button was drawn over the column beside the rail. Rounded UP from 59.5:
 * half a pixel of overlap is still overlap.
 *
 * Re-measuring is reproducible rather than a matter of opinion: open a
 * `hiddenInset` window at a known position, `screencapture -R` its bounds, and
 * find the coloured discs. Do that before editing this number.
 */
export const TRAFFIC_LIGHT_WIDTH = 60;

/**
 * Breathing room between the buttons and the first thing in the title bar.
 *
 * Not optional polish. Clearing them by arithmetic alone leaves half a pixel,
 * which reads exactly as reported — "very little spacing between the icon and
 * the buttons" — because a control that merely fails to overlap still looks
 * crammed against them. The rail's own `px-3` for the same reason: a gap the
 * eye already reads as "a gap" elsewhere in the shell.
 */
export const TRAFFIC_LIGHT_GAP = 12;

/**
 * Where the title bar's own content starts.
 *
 * This lives HERE, in the one module main and the renderer share, because the
 * two own different halves of one fact — main POSITIONS the buttons, the
 * renderer RESERVES room for them — and a copy on each side is a pair that
 * drifts in silence: nothing fails, the buttons simply start overlapping again.
 */
export const TITLEBAR_CONTENT_INSET =
  TRAFFIC_LIGHT_INSET.x + TRAFFIC_LIGHT_WIDTH + TRAFFIC_LIGHT_GAP;

/**
 * The shell's column widths.
 *
 * Shared rather than spelled as Tailwind classes because the title bar has to
 * AGREE with them: it spans the window above the columns and carries a divider
 * on the boundary between the leading columns and the content pane, with the
 * title centred over what is to the right of it. A divider that does not land
 * exactly on the border below it is the thing that was reported — the band has
 * to read as one piece with the layout under it, not merely near it.
 */
export const RAIL_COLLAPSED_WIDTH = 64;
export const RAIL_EXPANDED_WIDTH = 220;
/**
 * The chat list's DEFAULT width — what it opens at before anyone drags it.
 *
 * It was the width, full stop, until the column became resizable like the
 * agents panel on the other edge ("Left sidebar with threads list should be
 * resizible, same as right sidebar with agents"). The live value now lives in
 * `usePanelWidth`'s localStorage under `chats.listWidth`, and this is only the
 * seed for an install that has never dragged it. It stays HERE rather than
 * beside the two rail widths' users because it is the same kind of fact and
 * moving it would be a rename for its own sake.
 */
export const CHAT_LIST_WIDTH = 260;

// ─────────────────────────────────────────────────────────────────────────────
// System notifications (a banner outside the app, for a thread nobody is
// watching — see main/notify.ts)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Why a thread is worth interrupting the user for.
 *
 * The renderer reports the KIND and main decides whether it becomes a banner —
 * the renderer never reads the toggle. That is what makes a flipped switch take
 * effect at once instead of whenever a screen last cached its settings, and it
 * keeps the one place that can post a banner the one place that gates it.
 * `share-sign-in` is an agent's share waiting on the user signing in to the
 * place it shares to. `resource-alert` is the daemon's resource watch finding a
 * thread eating memory, or the machine short of memory or disk.
 */
export type RunNotificationKind =
  'question' | 'turn-end' | 'share-sign-in' | 'resource-alert';

/** One notification the renderer asks main to post. */
export interface RunNotification {
  kind: RunNotificationKind;
  /** The run it is about — clicking the banner opens this chat. */
  runId: string;
  /** The thread's sidebar label, so the banner names which chat. */
  title: string;
  /** One line under the title. */
  body: string;
  /**
   * Whether this banner may be withdrawn later (`retractNotification`) — a turn
   * that ended with a command it started still running, whose agent may only be
   * waiting on it. Absent on every banner that is final.
   */
  retractable?: boolean;
}

// ─────────────────────────────────────────────────────────────────────────────
// CLI detection
// ─────────────────────────────────────────────────────────────────────────────

/** CLI agents geniro can drive in v1 (all headless). */
export type CliKind = 'claude' | 'cursor-agent' | 'codex';

/**
 * Every CLI kind, keyed so the compiler rejects a record missing one: an array
 * typed `readonly CliKind[]` accepts any subset, and `CLI_KINDS` is what
 * settings validation keys on, so a kind left out of it has its settings
 * dropped on read with nothing failing. Key order is the onboarding display
 * order.
 */
const CLI_KIND_RECORD = {
  claude: true,
  'cursor-agent': true,
  codex: true,
} satisfies Record<CliKind, true>;

/** Every CLI kind, in onboarding display order. */
export const CLI_KINDS: readonly CliKind[] = Object.keys(
  CLI_KIND_RECORD,
) as CliKind[];

/**
 * Whether one AGENT CLI has a newer version of itself available.
 *
 * Not to be confused with `UpdateState` further down, which is geniro's OWN
 * self-update. These are the user's binaries: they ship their own updaters,
 * geniro neither hosts nor fetches anything for them, and pressing the control
 * runs that CLI's own `update`. The two are near neighbours in this file and
 * must stay two — one is about this app, the other about the tools it drives.
 *
 * Three states for `available`, on {@link CliDetection.loggedIn}'s reasoning:
 * `true`/`false` are answers the CLI GAVE, and `null` means nobody knows —
 * either the CLI has no check that stops short of installing (claude, measured;
 * see its descriptor's `latestProbe` in `main/agents/claude.ts`) or the probe
 * failed. It is never derived by comparing two version strings under an
 * ordering of geniro's own: their ordering is the vendor's, and a wrong guess
 * either nags about an update that does not exist or hides one that does. The
 * one comparison made here MIRRORS the vendor's published rule — codex records
 * its last check without a verdict, so its card applies codex's own `is_newer`
 * (`main/agents/codex.ts`).
 */
export interface CliUpdateState {
  /** The CLI said a newer version exists. `null` = not known — never guessed. */
  available: boolean | null;
  /** The newest version the CLI named, when it named one. */
  latestVersion: string | null;
  /**
   * Why this CLI cannot be ASKED what the latest version is; null when it can.
   *
   * A property of the CLI rather than a failure — claude's `update` checks and
   * installs in one step — so it is SAID on the card instead of leaving the row
   * to read as "no update exists", which is the one thing it does not mean.
   */
  checkUnavailableReason: string | null;
}

/** What running one CLI's own updater actually did. */
export interface CliUpdateResult {
  kind: CliKind;
  /** The updater exited cleanly. */
  ok: boolean;
  /**
   * `--version` as GENIRO read it either side of the run — its own measurement,
   * not the updater's prose. Which is the point: the two CLIs word their output
   * differently and are free to reword it, while "what does the binary answer
   * now" is a fact this app can take for itself and cannot get wrong.
   */
  previousVersion: string | null;
  version: string | null;
  /** The updater's own last words — shown only when it failed. */
  output: string | null;
  /**
   * One sentence on WHY it failed, distilled from {@link output}; null on
   * success.
   *
   * The output alone was REPORTED unreadable: codex's updater ran
   * `npm install -g`, npm's global prefix was `/usr/local` while codex lived
   * under `~/.local`, and the card said only "Update failed" over forty lines of
   * npm boilerplate on hover. Built in main, because only main can resolve the
   * binary's real path and so tell "no permission" from "installing somewhere
   * other than the copy in use".
   */
  reason: string | null;
}

/** What running one CLI's own installer actually did. */
export interface CliInstallResult {
  kind: CliKind;
  /**
   * The installer exited cleanly AND the binary it put down answers
   * `--version` — geniro's own measurement, never the script's prose, which
   * is exactly {@link CliUpdateResult}'s rule one step earlier.
   */
  ok: boolean;
  /** `--version` as the installed binary answered it, when it did. */
  version: string | null;
  /** Where detection now finds the binary, when it does. */
  path: string | null;
  /** The installer's own last words — shown only when it failed. */
  output: string | null;
  /** One sentence on why it failed; null on success. */
  reason: string | null;
}

/** Result of probing the host for a single CLI agent. */
export interface CliDetection {
  kind: CliKind;
  /** True when the binary was located and reported a version. */
  found: boolean;
  /** Absolute path to the resolved binary, when found. */
  path: string | null;
  /** Version string the binary reported, when found. */
  version: string | null;
  /**
   * Whether the CLI reports itself signed in, for a CLI that can be asked.
   *
   * Three states, and the third is why this is not a plain boolean: `true` /
   * `false` are answers the CLI gave, and `null` means nobody knows — either the
   * CLI has no status command to ask, or the probe itself failed. A failed probe
   * must NOT read as signed-out: the readiness chip would tell the user to sign
   * in when they already are, and the sign-in it offers would fix nothing.
   *
   * Whether a CLI can be asked is its descriptor's `loginProbe`
   * (`main/agents/<cli>.ts`) — claude's is `claude auth status --json`,
   * probe-verified.
   */
  loggedIn: boolean | null;
  /**
   * The same three-state answer per named configuration, keyed by directory —
   * for a CLI whose config directory carries the account (claude). Empty for
   * one whose does not, and for a CLI that was not found; absent from a
   * detection built by anything but `detectClis` (a fixture, a stub), which
   * reads exactly like "not asked".
   */
  profileLogins?: Record<string, boolean | null>;
  /** Whether this CLI has a newer version of itself to install. */
  update: CliUpdateState;
}

// ─────────────────────────────────────────────────────────────────────────────
// Git (the composer's branch chip — read from the folder a run will use)
// ─────────────────────────────────────────────────────────────────────────────

/** One branch of this repo that a DIFFERENT worktree has checked out. */
export interface BranchWorktree {
  branch: string;
  /** Absolute path of the worktree holding it — a folder a run can use. */
  path: string;
}

/** Git state of a working directory; every field is safe on a non-repo. */
export interface GitInfo {
  /** False for a plain folder — the branch chip renders only when true. */
  isRepo: boolean;
  /** Current branch, or null on a detached HEAD (no branch to name). */
  branch: string | null;
  /** Local branches, for the picker. */
  branches: string[];
  /** Working tree has uncommitted changes — blocks a branch switch. */
  dirty: boolean;
  /**
   * Branches OTHER worktrees of this repo hold — git will not check any of them
   * out here, whatever the tree looks like.
   *
   * They stay in {@link branches}: the branch exists, and it is one the user can
   * work on — just from the folder that holds it. What this field buys is that
   * the picker can say where, and the refusal can offer that folder instead of
   * reporting a dead end.
   */
  worktrees: BranchWorktree[];
  /**
   * The repository's MAIN checkout, when this folder is a linked worktree of it
   * — null for the main checkout itself and for a plain folder.
   *
   * A task's agent works in a worktree geniro cuts under its own data directory
   * and names by the task's id, so that folder's name says nothing about which
   * repository it belongs to: REPORTED as a chat header reading
   * `794addc7-273d-4924-8…`, which looked like the agent had been given the
   * wrong directory. This is what lets the header name the repository.
   */
  worktreeOf: string | null;
}

/**
 * Where a folder stood at ONE moment — stamped onto a chat when it is created,
 * so "what changed since this conversation started" has a fixed point.
 *
 * Its own shape rather than two fields on {@link GitInfo}, which is read on
 * every folder change to draw a chip: this is taken once per chat, and the two
 * answer different questions about the same folder. Both fields are null
 * whenever the reading could not be taken at all — a plain folder, a checkout
 * with no commits, no `git` on PATH.
 */
export interface GitStamp {
  /** Full commit id of HEAD, or null when there was none to read. */
  sha: string | null;
  /**
   * Whether the tree already carried uncommitted changes — null means the
   * question was never answered, which is NOT the same as clean and must not be
   * rendered as it.
   */
  dirty: boolean | null;
}

/** The repository a folder belongs to, and its checked-out branch — what line totals are keyed by. */
export interface GitHead {
  /** The repository's top-level directory, as git prints it. */
  root: string;
  /** The branch checked out, or null on a detached HEAD or when it could not be read. */
  branch: string | null;
}

/** What happened to one file since a chat's starting commit. */
export type GitChangeStatus =
  | 'added'
  | 'modified'
  | 'deleted'
  | 'renamed'
  | 'copied'
  /**
   * Created and never `git add`ed — invisible to `git diff <sha>`, and the case
   * the view is paired with `ls-files --others` to catch. Its own status rather
   * than folded into `added`, because the two are different facts about the
   * tree and only this one is at risk of being lost by a checkout.
   */
  | 'untracked';

/** One file's change, with the diff to draw for it. */
export interface GitChange {
  /** Path as git names it — relative to the repository root. */
  path: string;
  status: GitChangeStatus;
  /**
   * The unified diff for this file, or null when there is none to show — an
   * untracked file past the per-read body budget, or a diff git could not
   * produce. Null is "no body", never "no change".
   */
  diff: string | null;
  /**
   * Lines this file's diff adds and removes, counted from the RAW body before
   * it was capped for display.
   *
   * Both are null together, and null means NOT MEASURED rather than zero —
   * there was no body to count (an untracked file past the budget), or the body
   * is binary and has no lines to speak of. A renderer must draw nothing for a
   * null rather than a `+0 −0`, which would assert a file changed by nothing.
   */
  added: number | null;
  removed: number | null;
}

/**
 * What a folder holds now that it did not at a chat's starting commit.
 *
 * `unavailableReason` is the ONE failure shape, on `readGitInfo`'s rule: the
 * caller is deciding whether to draw a view, and an empty list with no reason
 * would claim nothing changed about a folder nobody could read.
 */
export interface GitChanges {
  changes: GitChange[];
  /** More files changed than one read returns — the list is real but short. */
  truncated: boolean;
  unavailableReason: string | null;
  /**
   * The checkout no longer descends from the chat's starting commit — a branch
   * switched, a pull request checked out — so `changes` is measured against
   * HEAD (what is uncommitted now) rather than that commit, which would list
   * every file the two branches disagree on.
   */
  movedOffStart: boolean;
  /**
   * What `changes` is measured against INSTEAD of the start, when the checkout
   * shares newer history with the remote than the start — upstream work pulled
   * in, or the chat's own commits merged: the newest commit HEAD shares with
   * the folder's pull request's base branch, else the default remote branch, so
   * everything already there is left out. Null when the start itself is the
   * base — nothing newer shared, no remote to ask, or `movedOffStart`.
   */
  upstreamBase: GitUpstreamBase | null;
}

/** The commit a changes list is measured against, and the ref it came from. */
export interface GitUpstreamBase {
  sha: string;
  /** Short and as git names it — `origin/main`, `origin/feature/stack`. */
  ref: string;
}

/**
 * An open pull request of the thread, as a read of a folder's changes needs it:
 * a branch stacked on another counts from that branch, the way GitHub counts it.
 */
export interface ChangesPullRequest {
  /** `owner/repo`, since a thread's pull requests can span repositories. */
  repository: string;
  headRefName: string;
  /** Absent when gh did not report it; the branch name then decides alone. */
  headRefOid?: string;
  baseRefName: string;
}

/**
 * The lines a {@link GitChanges} listing adds and removes, summed over its files.
 *
 * `partial` marks a total that is a floor rather than the figure: some file's
 * lines were not counted ({@link GitChange.added} is null), or the list they
 * were summed over was cut ({@link GitChanges.truncated}). A consumer must say
 * so rather than present it as the whole.
 */
export interface ChangesTotals {
  linesAdded: number;
  linesRemoved: number;
  partial: boolean;
}

/**
 * Why a total could not be measured, when the caller can do something about it: the commit
 * it was asked to measure against is gone, or the checkout no longer descends from it. A
 * folder baseline in that state is replaced (`POST /v1/stats/line-baselines`).
 */
export interface ChangesBaseUnreachable {
  baseUnreachable: true;
}

/**
 * The outcome of preparing a task's worktree.
 *
 * A RESULT rather than a throw, on `BranchSwitchResult`'s own terms: this
 * crosses IPC, where an exception arrives as a string with its shape gone, and
 * the caller has a real decision to make on a failure — it must not go on to
 * start a run against a worktree that was never made.
 */
export interface TaskWorktreeResult {
  ok: boolean;
  /** Where the agent will work; null when the worktree could not be made. */
  path: string | null;
  /** The branch it has checked out; null on failure. */
  branch: string | null;
  /**
   * Whether this was the task's OWN worktree, already standing and handed back
   * as it was rather than made now. A caller whose start is then refused must
   * leave a reused one alone: another run of this same task may be why the
   * start was refused, and be working in it. False on failure.
   */
  reused: boolean;
  /** Why it failed, as git's own first line; null on success. */
  error: string | null;
}

/**
 * What became of a finished card's worktree.
 *
 * Two facts rather than one, because "kept" has two causes a caller may want
 * to tell apart: nothing could be committed (hooks refused it, or the machine
 * has no git identity), or git could not say what was in there at all.
 */
export interface TaskWorktreeSettleResult {
  /** Whether the directory is gone. False means it is still on disk. */
  removed: boolean;
  /** Whether a rescue commit was made first. False on an already-clean tree. */
  committed: boolean;
}

/** Outcome of a guarded branch switch. `branch` is the branch now checked out. */
export interface BranchSwitchResult {
  ok: boolean;
  branch: string | null;
  /** Why the switch was refused or failed; null on success. */
  error: string | null;
  /**
   * The switch was REFUSED over uncommitted work, rather than having failed.
   *
   * The difference is the whole of how it reads: a failure is something that
   * went wrong, while this is the guard doing its job on a tree the user is
   * mid-edit in. It drives a warning tone instead of a red error, and the
   * offer to pull the branch up to date without losing that work.
   */
  dirty: boolean;
  /**
   * The switch was refused because ANOTHER WORKTREE holds that branch — this is
   * the path of that worktree, and null for every other outcome.
   *
   * A path rather than a flag, because the way out is that folder: git will
   * never check the branch out twice, so the offer is to point the run at the
   * worktree that already has it. Reported as its own field for the same reason
   * {@link dirty} is — the alternative is the renderer recognising the case by
   * matching git's own sentence, which is locale-dependent prose.
   */
  worktree: string | null;
}

/**
 * Outcome of "bring this branch up to date and keep my changes" — a stash, a
 * fast-forward, and the stash put back.
 */
export interface BranchPullResult {
  ok: boolean;
  /** The branch that was pulled, or null when there was none to pull. */
  branch: string | null;
  /** git's own first line when it refused; null on success. */
  error: string | null;
  /**
   * The work was stashed and could NOT be put back — the stash is still there,
   * named here so the user can reach it. Null whenever nothing was stashed or
   * it went back cleanly.
   */
  stashLeft: string | null;
}

/**
 * Outcome of "switch to that branch and bring my changes along" — a stash, the
 * switch, and the stash put back on the new branch.
 */
export interface BranchCarryResult {
  ok: boolean;
  /** The branch now checked out, or null when the folder is no repository. */
  branch: string | null;
  /** git's own first line when it refused; null on success. */
  error: string | null;
  /** As {@link BranchPullResult.stashLeft}. */
  stashLeft: string | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Pull requests (read from the folder a run works in, through the user's own gh)
// ─────────────────────────────────────────────────────────────────────────────

/** What GitHub says a pull request is doing — `gh`'s own three states. */
export type PullRequestState = 'open' | 'merged' | 'closed';

/** One pull request on the repo a folder belongs to. */
export interface PullRequestInfo {
  number: number;
  title: string;
  state: PullRequestState;
  /** Open, but not yet asking for review — a state of its own on screen. */
  isDraft: boolean;
  /**
   * The branch it merges FROM. This is what ties a PR to a folder: the "current
   * PR" of a run is the one whose head branch is that folder's checked-out
   * branch, which is why no branch is stored on the run itself.
   */
  headRefName: string;
  /**
   * It comes from a FORK, so {@link headRefName} names a branch in someone
   * else's repository, and no ref of this clone.
   */
  isCrossRepository: boolean;
  /**
   * GitHub login owning the repo {@link headRefName} lives in, or null when
   * that repo is gone — a deleted fork, which GitHub's own schema allows and
   * which must still be listed rather than dropped.
   */
  headRepositoryOwner: string | null;
  /** GitHub login of whoever opened it. */
  author: string;
  url: string;
  updatedAt: string;
  /**
   * When GitHub says it merged, as the ISO time gh reports — ABSENT for a pull
   * request that has not merged, or when gh gave no readable time.
   *
   * What the merge watcher judges a card's round by: a card that has been Done
   * before is ended only by a merge that happened after it last got there, and
   * this is the one place that fact exists. Optional rather than nullable so
   * the many renderer fixtures that build a pull request need not name it.
   */
  mergedAt?: string;
  /** The branch it merges INTO, absent when gh gave no readable name. */
  baseRefName?: string;
  /** The commit {@link headRefName} is at, absent when gh gave none. */
  headRefOid?: string;
  /**
   * How big it is: lines added, lines removed, files touched — as GitHub itself
   * counts them, over the whole pull request rather than the working tree.
   *
   * Null is NOT MEASURED and never zero: gh was not asked, is too old to answer,
   * or gave something unreadable. A surface draws nothing for a null, on the
   * same rule the git-side {@link GitChange} counts follow.
   */
  added: number | null;
  removed: number | null;
  changedFiles: number | null;
}

/**
 * The pull requests on a folder's checked-out branch, newest first.
 *
 * Head-filtered at the query — every surface in the app is scoped to the thread
 * (`chats/use-thread-pull-requests.ts`), so the repo's other branches are never
 * fetched.
 *
 * There is no "did it work" flag, deliberately. Every failure — no `gh` on the
 * machine, a `gh` that is not signed in, a folder that is not a GitHub checkout,
 * a query that errored — arrives as the empty list, because the answer to all of
 * them is the same: draw no pull-request surfaces at all, the way
 * {@link GitInfo} `isRepo: false` hides the branch chip. An error banner about a
 * CLI the user may have no intention of installing would be worse than silence.
 */
/**
 * One pull request to ask GitHub about, addressed the way a THREAD knows it.
 *
 * The IPC argument shape, not a daemon type. It overlaps structurally with the
 * daemon's `RunPullRequest` because both describe the same four facts, and the
 * renderer MAPS one to the other (`refOf`) rather than passing the wire object
 * through: this side has no `seq`, which is a transcript position and means
 * nothing here, and a cast would quietly couple an Electron channel to a
 * generated type it must be free to diverge from.
 */
export interface PullRequestRef {
  owner: string;
  repo: string;
  number: number;
  url: string;
}

/**
 * What GitHub could say about one {@link PullRequestRef}.
 *
 * The ref always comes back and `pullRequest` may be null: the thread demonstrably
 * opened it — that is why it is in the list — so an unanswerable lookup (no
 * `gh`, a logged-out CLI, a repository this account cannot see) must still
 * leave a row that links to it, rather than making the pull request disappear
 * because its STATE could not be read.
 */
export interface PullRequestRefResult {
  ref: PullRequestRef;
  pullRequest: PullRequestInfo | null;
}

/**
 * Where a saved file ended up — or that the user closed the dialog.
 *
 * `saved: false` is the CANCEL, and it is the reason this is a result rather
 * than a bare `Promise<string | null>` that a caller could read as a failure:
 * closing a save dialog is the commonest thing to do with one, and it deserves
 * silence rather than an error strip. A write that genuinely fails rejects.
 *
 * ONE shape for every save channel rather than one per feature. What differs
 * between a chat export and an artifact is the document and the filters, which
 * live in each channel's own input and in main's writer; where it landed and
 * whether the user went through with it is the same answer, and two identical
 * interfaces is how the two would come to drift.
 */
export interface FileSaveResult {
  saved: boolean;
  /** Where it was written; null when the dialog was cancelled. */
  path: string | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Secrets — none. The app stores no credentials.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Every CLI authenticates from its own login, so the app holds no credential.
 * The "secrets live in the macOS Keychain only — never in SQLite, never in a
 * file" rule still governs the moment one is ever needed.
 */

// ─────────────────────────────────────────────────────────────────────────────
// IPC contract (window.geniro — exposed by the preload via contextBridge)
// ─────────────────────────────────────────────────────────────────────────────

/** Why a browser tab's last load did not finish. */
export interface BrowserTabError {
  code: number;
  description: string;
  url: string;
  /** A certificate error, which the user alone may continue past for its host. */
  certificate: boolean;
}

/** A page's basic-auth challenge, waiting for the user's answer. */
export interface BrowserAuthRequest {
  host: string;
  realm: string;
}

/** One tab of a chat's in-app browser, as main reports it. */
export interface BrowserTabState {
  id: string;
  url: string;
  title: string;
  loading: boolean;
  canGoBack: boolean;
  canGoForward: boolean;
  error: BrowserTabError | null;
  /** The agent or member that opened the tab, or null for the user. */
  openedBy: string | null;
  /** The label of an own-cookie tab, or null when it uses the chat's cookies. */
  ownCookiesLabel: string | null;
  /** The agent or member running an operation on the tab right now. */
  drivenBy: string | null;
  authRequest: BrowserAuthRequest | null;
  /** What the tab is for, set by an agent or the user; null shows the page title. */
  name: string | null;
  color: ProfileColor | null;
}

/** A rename or recolour of one tab; a field left out is unchanged, null clears it. */
export interface BrowserTabLabel {
  name?: string | null;
  color?: ProfileColor | null;
}

/** One chat's in-app browser: its tabs, which one shows, and where it is drawn. */
export interface BrowserRunState {
  runId: string;
  tabs: BrowserTabState[];
  activeTabId: string | null;
  poppedOut: boolean;
  /** Addresses opened in this chat since launch, newest first. */
  recent: string[];
}

/** A change to one chat's browser, pushed by main. */
export interface BrowserStateEvent {
  state: BrowserRunState;
  /** Set when an agent has just opened this tab: the pane opens for it once. */
  agentOpenedTabId: string | null;
  /** Set when the browser has just come back from its own window: the chat's column opens for it. */
  dockedBack: boolean;
}

/** Where the pane's placeholder sits in the window, in CSS pixels. */
export interface BrowserBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

export type BrowserHistoryAction = 'back' | 'forward' | 'reload' | 'stop';

export type BrowserTabAction =
  'devtools' | 'clearCookies' | 'openExternal' | 'copyUrl';

/** Input captured by the onboarding flow and committed in one IPC call. */
export interface OnboardingInput {
  lastChatTarget?: CliKind;
  /** Per-agent binary path overrides (absolute paths); omitted keys auto-detect. */
  cliPaths?: Partial<Record<CliKind, string>>;
}

/** What showing an artifact page's folder or file in Finder did, or why it showed nothing. */
export type ArtifactPathOutcome =
  { shown: 'opened' | 'revealed' } | { shown: null; reason: string };

/**
 * The typed API surface the preload exposes on `window.geniro`. The renderer
 * never touches Node or Electron directly — every privileged action is one of
 * these channels.
 */
export interface GeniroApi {
  /** Current onboarding + daemon status. */
  getStatus(): Promise<{
    onboardingComplete: boolean;
    daemon: DaemonStatus;
    /**
     * Whether this is a packaged build. The renderer needs it for exactly one
     * thing: settings whose unchosen state resolves per build
     * (`resolveDaemonInspect`). A screen that showed the STORED `null` as
     * "off" would tell the user no debugger port is open while the dev daemon
     * is listening on one — and `import.meta.env.PROD` is not the same
     * question, since a built-but-unpackaged run answers it the other way.
     */
    isPackaged: boolean;
  }>;
  /** Daemon connection handle (host + port + token) for opening an authed WS. */
  getDaemonHandle(): Promise<DaemonHandle | null>;
  /**
   * Bring the daemon up if it is not running — the connection banner's Retry.
   *
   * {@link getDaemonHandle} only READS the handle, so a Retry built on it could
   * never bring back a daemon that died or failed to start: it asked for an
   * address nothing was listening on. This starts one (or answers with the one
   * already running) and rejects with the supervisor's own reason when it
   * cannot. Over the LAN gateway the handle comes back with its token and
   * address blanked, like `getStatus`'s.
   */
  ensureDaemon(): Promise<DaemonHandle>;
  /** Subscribe to daemon restarts that rotate the loopback handle/token. */
  onDaemonRestarted(listener: (handle: DaemonHandle) => void): () => void;
  /**
   * Subscribe to the data migration a starting daemon reports, step by step,
   * and null once that start has settled.
   */
  onDaemonMigrating(
    listener: (migration: DaemonMigration | null) => void,
  ): () => void;
  /**
   * Subscribe to the menu bar's Clear Agent Cache.
   *
   * A PUSH from the main process rather than a renderer control, because the
   * menu bar is where it was asked for — and the work is the renderer's: it
   * holds the daemon client, and it holds vocabulary caches of its own that the
   * daemon cannot reach.
   */
  onClearAgentCaches(listener: () => void): () => void;
  /**
   * The quit is about to stop the daemon: post the line measurements this window is still holding, then
   * answer {@link lineMeasurementsFlushed} with the id it was asked under (`main/line-measurement-flush.ts`).
   */
  onFlushLineMeasurements(listener: (requestId: string) => void): () => void;
  /**
   * The settings file was just written — by any window or a paired phone. No
   * payload: a view that shows figures derived from settings re-reads them.
   */
  onSettingsChanged(listener: () => void): () => void;
  /**
   * Open the native folder picker; returns the chosen absolute path or null.
   *
   * `defaultPath` is where the dialog OPENS — pass the folder the field already
   * holds. Without it macOS reopens wherever the last dialog was left, which
   * put the task panel's picker in the PARENT of the project's folder, listing
   * it among its siblings, and read as the task using the wrong directory.
   */
  pickProjectFolder(defaultPath?: string): Promise<string | null>;
  /** Open the native file picker for an agent binary; returns the path or null. */
  pickAgentBinary(): Promise<string | null>;
  /**
   * Files to attach to a task, by absolute path — several at once, since
   * attaching is routinely a set (a bundle and its manifest, three
   * screenshots). Empty when the user cancelled.
   *
   * A PICKER and not an upload: geniro copies nothing, so what crosses here is
   * the paths of files that stay exactly where the user put them.
   */
  pickTaskFiles(): Promise<string[]>;
  /** Read the persisted settings. */
  getSettings(): Promise<Settings>;
  /** Merge a partial patch into settings; returns the updated settings. */
  updateSettings(patch: Partial<Settings>): Promise<Settings>;
  /**
   * Probe the host for each supported CLI agent. With `maxAgeMs`, a detection
   * main made within that long is answered instead of probing again.
   */
  detectClis(options?: { maxAgeMs?: number }): Promise<CliDetection[]>;
  /**
   * Update one agent CLI by running ITS OWN updater, and report what changed.
   *
   * geniro downloads nothing here and hosts nothing: the binary updates itself,
   * exactly as it would in the user's terminal. Slow by nature (claude's native
   * build is ~200MB), so the caller shows a spinner and must not race a second
   * press against it.
   */
  updateCli(kind: CliKind): Promise<CliUpdateResult>;
  /**
   * Install one agent CLI on a machine that does not have it, by running the
   * VENDOR's own installer (`main/agents/<cli>.ts` → `installer`), and report
   * whether the binary it put down now answers.
   *
   * Like {@link updateCli}, geniro hosts nothing and keeps nothing: the
   * vendor's script downloads the vendor's build. Minutes rather than seconds,
   * and never rejects — every failure is reported inside the result.
   */
  installCli(kind: CliKind): Promise<CliInstallResult>;
  /** Persist onboarding input and mark onboarding complete. */
  completeOnboarding(input: OnboardingInput): Promise<Settings>;
  /** Open a native picker for a team YAML to import; path or null. */
  pickTeamImport(): Promise<string | null>;
  /** Open a native save dialog for a team export; target path or null. */
  pickTeamExport(defaultName: string): Promise<string | null>;
  /** The current update state, for a screen that just mounted. */
  getUpdateState(): Promise<UpdateState>;
  /**
   * Check the GitHub Releases feed NOW, resolving with the resulting state.
   *
   * The same check the launch and the periodic timer run — a manual press is
   * not a second code path, it only skips the wait.
   */
  checkForUpdates(): Promise<UpdateState>;
  /**
   * Download, verify and swap in the available update.
   *
   * Resolves with the state at the END of the attempt: `error` when it could
   * not be applied, otherwise `ready`. It does NOT restart the app — see
   * {@link relaunchForUpdate}.
   */
  installUpdate(): Promise<UpdateState>;
  /**
   * Quit and come back up on the freshly-installed bundle.
   *
   * Separate from {@link installUpdate} because restarting takes the daemon and
   * every running turn with it, so the moment is the user's to pick. A no-op
   * unless an update is actually `ready`.
   */
  relaunchForUpdate(): Promise<UpdateState>;
  /** Subscribe to update-state changes (check progress, download progress). */
  onUpdateState(listener: (state: UpdateState) => void): () => void;
  /** Read a folder's git state (repo? branch? branches? dirty?). */
  getGitInfo(dir: string): Promise<GitInfo>;
  /**
   * Read where a folder stands right now — the commit and the dirty flag a new
   * chat is stamped with. Two subprocesses, against {@link getGitInfo}'s five.
   */
  getGitStamp(dir: string): Promise<GitStamp>;
  /**
   * The repository a folder belongs to and its branch, or null when it is not a repository
   * with a commit. Desktop only: the line measurement that reads it is silent on a remote
   * device.
   */
  getGitHead(dir: string): Promise<GitHead | null>;
  /**
   * Read what a folder holds now that it did not at `sha` — the chat's own
   * starting commit ({@link GitStamp}).
   *
   * READ-ONLY, and the view built on it offers no revert: it says what happened,
   * and undoing any of it is the user's own git, where they can see what they
   * are undoing.
   *
   * `workFolder` marks a worktree one of the thread's agents made, measured
   * from where its history meets `sha` when it does not descend from it.
   * `pullRequests` are the thread's open ones; the one `dir` is on sets the base.
   */
  getChangesSince(
    dir: string,
    sha: string,
    workFolder?: boolean,
    pullRequests?: readonly ChangesPullRequest[],
  ): Promise<GitChanges>;
  /**
   * The repository's LINKED worktrees other than `dir`'s own — never the main
   * checkout, nor one whose directory is gone — as real paths, empty when git
   * cannot answer. Candidates only: which of them a thread worked in is the
   * daemon's answer from the thread's own transcript. Only worktrees made
   * since `startedAtMs` (the thread's start), never geniro's own task ones.
   */
  listWorktrees(dir: string, startedAtMs: number): Promise<string[]>;
  /**
   * The lines a folder has added and removed since `sha`, tracked and untracked files
   * together — for a readout that wants the figures and not the diffs, so it is counted
   * with `--numstat` rather than by reading every diff.
   *
   * `null` means the changes could not be read (not a repository, git failed) and is never
   * a zero: `+0 −0` would assert that nothing changed in a folder nobody could read.
   * {@link ChangesBaseUnreachable} means `sha` itself is unusable. `partial` flags a total
   * that is a floor — see {@link ChangesTotals}.
   */
  getChangesTotals(
    dir: string,
    sha: string,
  ): Promise<ChangesTotals | ChangesBaseUnreachable | null>;
  /** Answer a quit-time {@link onFlushLineMeasurements}: this window has posted what it was holding. */
  lineMeasurementsFlushed(requestId: string): Promise<void>;
  /**
   * Open the user's own terminal on a command — the handoff out of geniro.
   * Takes the command as DATA (never a shell string) so nothing here has to
   * quote it, and so the renderer cannot smuggle a second command in.
   */
  openInTerminal(input: {
    command: string;
    args: string[];
    cwd: string;
    /**
     * Env the invocation needs, composed by the DAEMON (the run's config
     * directory — which account the conversation belongs to). Passed through
     * verbatim: this side names no variable, exactly as it names no flag.
     */
    env?: Record<string, string>;
  }): Promise<void>;
  /**
   * Start a login shell on a PTY for one tab of the in-app terminal panel.
   * The id is minted by the RENDERER, so it can subscribe to
   * {@link onTerminalData} before the shell has printed anything. Rejects when
   * the folder is gone or the id is taken.
   */
  terminalCreate(input: TerminalCreateInput): Promise<void>;
  /** Keystrokes and pastes, verbatim. A no-op for a shell that already exited. */
  terminalWrite(id: string, data: string): Promise<void>;
  terminalResize(id: string, cols: number, rows: number): Promise<void>;
  /**
   * The view has drawn `chars` characters of this shell's output. Main stops
   * reading a shell whose output is running too far ahead of these.
   */
  terminalAck(id: string, chars: number): Promise<void>;
  /** Hang the shell up; its {@link onTerminalExit} follows. */
  terminalKill(id: string): Promise<void>;
  /** Output of every shell this window owns, coalesced into small batches. */
  onTerminalData(listener: (event: TerminalDataEvent) => void): () => void;
  onTerminalExit(listener: (event: TerminalExitEvent) => void): () => void;
  /**
   * Ask where to keep a chat export, and write it there.
   *
   * Both halves on one channel because the renderer already HOLDS the document
   * — see `main/save-chat-export.ts` for why that differs from
   * {@link pickTeamExport}, whose bytes live in the daemon. A cancelled
   * dialog resolves `saved: false`, which is an outcome and not an error.
   *
   * BOTH renderings go across and main writes the one the user's chosen filename
   * asks for: the format is picked in an AppKit save panel, which is a surface
   * only main can read.
   */
  saveChatExport(input: {
    /**
     * A bare file name to suggest, with NO extension — main appends the one
     * matching the filter it opens on. Never a path; main refuses separators.
     */
    suggestedName: string;
    /** The complete document, for a machine or a maintainer. */
    json: string;
    /** The readable rendering, for a person. */
    markdown: string;
  }): Promise<FileSaveResult>;
  /**
   * Ask where to keep a published artifact, and write it there as ONE HTML
   * file the user can send to somebody.
   *
   * Its own channel rather than a second format on {@link saveChatExport},
   * because they save different things: that one offers two renderings of a
   * conversation and lets the save panel pick, this one has exactly one
   * rendering of one document and no choice to make. Sharing a channel would
   * mean a filter list that is right for neither.
   *
   * The document is ONE file by construction — the page's own CSP admits no
   * external subresource but libraries from the fixed public CDNs, so there is
   * nothing of the page's own beside it to gather up.
   */
  saveArtifact(input: {
    /**
     * A bare file name to suggest, with NO extension — main appends `.html`.
     * Never a path; main refuses separators.
     */
    suggestedName: string;
    /** The complete document, theme baked in, ready to open on its own. */
    html: string;
  }): Promise<FileSaveResult>;
  /**
   * Ask where to keep the shared-memory export, and write the given Markdown
   * there as `geniro-memory-<YYYY-MM-DD>.md` (main composes the name). The
   * renderer fetched the text from the daemon; a cancelled dialog resolves
   * `saved: false`, which is an outcome and not an error.
   */
  saveMemoryExport(markdown: string): Promise<FileSaveResult>;
  /**
   * Ask where to keep a knowledge export, and write the given Markdown there.
   * Refused from a paired device: the dialog would open on the Mac.
   */
  saveKnowledgeExport(input: {
    /** The daemon's file name; never a path, main refuses separators. */
    suggestedName: string;
    markdown: string;
  }): Promise<FileSaveResult>;
  /**
   * Make the worktree and branch a task's agent will work in.
   *
   * Here rather than in the daemon because every git call this app makes
   * belongs to the main process. The daemon is told the path afterwards and
   * records it; it never creates one.
   */
  prepareTaskWorktree(input: {
    taskId: string;
    folder: string;
  }): Promise<TaskWorktreeResult>;
  /**
   * Take down the worktree a task was given, keeping its BRANCH.
   *
   * Answers false when this app never made one for that task — the caller
   * cannot name a path, only a task, so nothing outside the registry is
   * reachable from here.
   */
  pruneTaskWorktree(taskId: string): Promise<boolean>;
  /**
   * Collect the worktree of a run that has SETTLED, keeping what is in it.
   *
   * Commits whatever the agent left uncommitted onto the task's own branch and
   * then removes the directory, so the routine end state of a run stops being
   * a checkout nothing ever collects. A commit that could not be made keeps
   * the worktree instead — the branch is the only place the work would
   * survive, so nothing is removed until it is on there.
   *
   * Separate from `pruneTaskWorktree`, which is the FAILED-START path and must
   * never commit: there is nothing of the agent's to rescue, and the only
   * changes in that directory would be the user's own.
   */
  settleTaskWorktree(taskId: string): Promise<TaskWorktreeSettleResult>;
  /**
   * Settings → Storage: size the data folder's entries the daemon did not
   * claim (its `unclaimed` answer) — the task worktrees one by one, the
   * window's caches, the rest of the app's own files.
   */
  getAppStorage(unclaimed: string[]): Promise<AppStorageUsage>;
  /**
   * Remove one entry of the worktrees directory on the user's press, named
   * by its directory name. Kept, with the reason, when work could be lost.
   */
  removeStorageWorktree(name: string): Promise<WorktreeRemoval>;
  /** Empty the window's HTTP and code caches; answers the space it freed. */
  clearBrowserCache(): Promise<{ freedBytes: number }>;
  /**
   * Restart the daemon, as a settings change that needs a fresh process does —
   * for a database compaction, which runs only at its start.
   */
  restartDaemon(): Promise<void>;
  /** Switch the folder to a branch — refused when the tree is dirty. */
  switchBranch(dir: string, branch: string): Promise<BranchSwitchResult>;
  /**
   * Fast-forward the folder's branch to its upstream, keeping uncommitted work:
   * stash → `git pull --ff-only` → stash pop.
   */
  pullBranch(dir: string): Promise<BranchPullResult>;
  /**
   * Switch the folder to a branch and keep uncommitted work, moving it along:
   * stash → `git switch` → stash pop.
   */
  carryChangesToBranch(dir: string, branch: string): Promise<BranchCarryResult>;
  /**
   * Live state for the pull requests a THREAD opened, addressed by URL.
   *
   * A batch rather than one call per thread: the sidebar draws many rows and
   * threads routinely share repositories, and the resolve is grouped by
   * repository — so one call for every thread on screen costs one `gh` query
   * per distinct repository instead of one per thread.
   */
  getPullRequestsByRef(refs: PullRequestRef[]): Promise<PullRequestRefResult[]>;
  /**
   * Show one of the daemon's own files in Finder — the debug log.
   *
   * Deliberately narrow: it REVEALS (selects in a file manager) rather than
   * opens, so nothing here can be talked into executing what it is handed, and
   * main refuses any path outside the daemon's log directory. The renderer is
   * sandboxed and a path it supplies is not trusted just because the daemon
   * gave it to us.
   */
  revealPath(
    path: string,
  ): Promise<{ revealed: boolean; reason: string | null }>;
  /**
   * Show a folder or file a button on an agent's artifact page names, in Finder: a
   * plain folder opens, anything else is revealed, so nothing is ever launched.
   * Desktop only.
   */
  openArtifactPath(path: string): Promise<ArtifactPathOutcome>;
  /**
   * Toggle Chrome DevTools on this window — the same Elements / Console /
   * Network panels a browser gives you, because the renderer IS a browser.
   *
   * It answers a different question from the debug panel and neither replaces
   * the other. DevTools sees ONE process, this one: the DOM, renderer
   * exceptions, and every HTTP call and `/ws` frame the renderer sends. It
   * cannot see the daemon or a spawned CLI at all — those are separate
   * processes with no page and no renderer network stack, which is why the
   * daemon log, the transcript stream and `agent-stdio` exist in the debug
   * panel instead, and why reaching the daemon's own internals needs
   * `daemonInspect` rather than this.
   *
   * Electron's default menu already binds this to ⌥⌘I; the button exists so it
   * is findable from the place a user already looks when something is wrong.
   */
  toggleDevTools(): Promise<void>;
  /**
   * Post a system notification about a run, if the user has that kind switched
   * on. Resolves either way — a notification the settings suppressed is not a
   * failure, and the caller has nothing to do about one that was.
   */
  notify(notification: RunNotification): Promise<void>;
  /**
   * Withdraw the RETRACTABLE banner still standing for a run, from the screen
   * and from Notification Centre. A no-op when there is none — never posted
   * (settings off, the chat on screen), already clicked, or a final one — and
   * none of those is the caller's to know.
   */
  retractNotification(runId: string): Promise<void>;
  /**
   * Post a banner the user explicitly asked for, and report what became of it.
   *
   * The one notification path with an ANSWER, and it needs one: every other is
   * fire-and-forget, so a user seeing no banners has no way to tell a setting
   * from a permission from a bug. It also spends the macOS authorisation prompt
   * deliberately — the system asks the first time an app posts and swallows
   * that notification to do it, so without this the first banner anyone should
   * have seen is always the one they never get.
   */
  testNotification(): Promise<{
    /** Whether the app posted at all (settings/platform can refuse first). */
    posted: boolean;
    /** What the platform reported: true shown, false refused, null silent. */
    shown: boolean | null;
    /** Why it did not arrive, in words for the user; null when it did. */
    reason: string | null;
  }>;
  /**
   * Open macOS's own Notifications pane, where an app the system is holding
   * gets un-held.
   *
   * The other half of {@link testNotification}: that one establishes that the
   * silence is the OS's doing, and this one goes to the only place the user can
   * do anything about it. It takes NO argument on purpose — the destination is
   * a constant in main, so a renderer cannot aim `shell.openExternal` at a pane
   * of its choosing.
   */
  openNotificationSettings(): Promise<void>;
  /**
   * A notification the user CLICKED, carrying the run it was about.
   *
   * The other half of `notify`: a banner you cannot act on only tells you to go
   * looking. Main raises and focuses the window; this is what lets the app open
   * the thread the banner named.
   */
  onNotificationActivated(listener: (runId: string) => void): () => void;
  /**
   * The LAN gateway's whole state — on/off, listening, the bound port, both
   * links, the live pairing code and its devices.
   *
   * Answers the WHOLE state rather than a delta because a paired phone reads
   * the identical channel over the gateway's own HTTP bridge (see
   * `main/remote/`), so there is exactly one shape for Settings and a phone
   * to agree on.
   */
  getRemoteAccess(): Promise<RemoteAccessState>;
  /**
   * Force a new pairing code, invalidating the current one. Answers the whole
   * state, like every remote-access channel, so the caller redraws from one
   * reply rather than a second round trip.
   */
  regenerateRemotePairingCode(): Promise<RemoteAccessState>;
  /**
   * Revoke one paired device's session token. A phone may call this on
   * itself or on another device it sees listed — neither touches the
   * WebContents that asked, which is why this is safe to allow remotely.
   */
  revokeRemoteDevice(deviceId: string): Promise<RemoteAccessState>;
  /**
   * Open a PUBLIC address for the LAN gateway, by starting a tunnel client
   * (cloudflared, else ngrok) the user has installed on this machine.
   *
   * geniro runs no relay of its own and the daemon still binds `127.0.0.1`:
   * this starts a child process that forwards a public name to the gateway
   * already listening on the Wi-Fi, under the same pairing gate. Answers the
   * whole state, like every remote-access channel.
   */
  startRemoteTunnel(): Promise<RemoteAccessState>;
  /** Close the public address. The LAN listener is left alone. */
  stopRemoteTunnel(): Promise<RemoteAccessState>;
  /** One chat's in-app browser as it stands. */
  browserState(runId: string): Promise<BrowserRunState>;
  /** Open a tab in a chat's browser, on an address or on the new-tab page; answers its id. */
  browserOpenTab(runId: string, url: string | null): Promise<string>;
  /** Load what the user typed in a tab's address bar (an address or words to search). */
  browserNavigate(runId: string, tabId: string, input: string): Promise<void>;
  browserHistory(
    runId: string,
    tabId: string,
    action: BrowserHistoryAction,
  ): Promise<void>;
  browserCloseTab(runId: string, tabId: string): Promise<void>;
  browserSelectTab(runId: string, tabId: string): Promise<void>;
  /** Place the chat's active tab over the pane, or hide it with null. */
  browserSetBounds(runId: string, bounds: BrowserBounds | null): Promise<void>;
  /** Move the chat's tabs into a window of their own, without reloading them. */
  browserPopOut(runId: string, title: string): Promise<void>;
  /** Move the chat's tabs back beside the chat. */
  browserDock(runId: string): Promise<void>;
  browserTabAction(
    runId: string,
    tabId: string,
    action: BrowserTabAction,
  ): Promise<void>;
  /** The user's "Continue anyway" past a certificate error, for that tab's host. */
  browserContinueInsecure(runId: string, tabId: string): Promise<void>;
  /** Answer a basic-auth challenge; null cancels it. */
  browserAnswerAuth(
    runId: string,
    tabId: string,
    credentials: { username: string; password: string } | null,
  ): Promise<void>;
  /** A still of the chat's active tab as a data URL, shown while an overlay covers the pane. */
  browserCapture(runId: string): Promise<string | null>;
  /** Close a deleted or archived chat's tabs and clear its cookies. */
  browserForgetRun(runId: string): Promise<void>;
  /** Stop the agent operation running on a tab. */
  browserStopAgent(runId: string, tabId: string): Promise<void>;
  /** The user's rename or recolour of a tab; an agent never overwrites what it sets. */
  browserLabelTab(
    runId: string,
    tabId: string,
    label: BrowserTabLabel,
  ): Promise<void>;
  /** Run one agent operation the daemon relayed (`browser_request`); answers its `browser_reply`. */
  browserAgentRequest(request: unknown): Promise<unknown>;
  onBrowserState(listener: (event: BrowserStateEvent) => void): () => void;
  /**
   * The absolute path of a file the OS handed the renderer — a paste, a drop.
   *
   * The one member here that is NOT an IPC channel, and it cannot be one: a
   * `File` is a renderer object with no representation main could be sent, and
   * Electron answers this from the renderer side (`webUtils.getPathForFile`,
   * which replaced the `File.path` property removed in Electron 32). So the
   * preload answers it itself, and it is SYNCHRONOUS — a paste handler has to
   * decide whether to swallow the event before it returns.
   *
   * Null when the file has no path on disk: one built in JS, or a paste that
   * carried bytes rather than a file.
   */
  filePath(file: File): string | null;
}

/**
 * The largest terminal size main accepts. Shared because the renderer CLAMPS to
 * it: a maximized window on a large display fits more columns than a sane bound,
 * and a size over it would refuse the shell outright.
 */
export const TERMINAL_MAX_COLS = 1000;
export const TERMINAL_MAX_ROWS = 500;

/** One tab's shell, as the renderer asks for it. `cwd` absent = home. */
export interface TerminalCreateInput {
  id: string;
  cwd?: string;
  cols: number;
  rows: number;
}

export interface TerminalDataEvent {
  id: string;
  data: string;
}

export interface TerminalExitEvent {
  id: string;
  /** 0 for a shell killed by a signal as well — read `signal` before trusting it. */
  exitCode: number;
  /** The signal that ended the shell; null when it exited on its own. */
  signal: number | null;
}

/**
 * The one {@link GeniroApi} member the preload answers itself — see
 * {@link GeniroApi.filePath}. Named so the exhaustiveness check below stays
 * exhaustive over everything that IS a channel.
 */
type PreloadLocalMethod = 'filePath';

export interface AppStorageEntry {
  name: string;
  bytes: number;
}

/** One entry of `<userData>/worktrees`, as Settings → Storage lists it. */
export interface StorageWorktree {
  /** Its directory name — what `removeStorageWorktree` takes. */
  name: string;
  bytes: number;
  kind: 'worktree' | 'folder' | 'file';
  /** The card it was made for, when the registry records it. */
  taskId: string | null;
  branch: string | null;
  /** Whether that card's work is finished; null when unknown or not a card's. */
  cardFinished: boolean | null;
}

export interface AppStorageUsage {
  worktrees: StorageWorktree[];
  browserCache: AppStorageEntry[];
  appData: AppStorageEntry[];
}

/** What a Remove press did to one worktree. */
export interface WorktreeRemoval {
  removed: boolean;
  /** Why it was kept; null once removed. */
  reason: string | null;
}

